// Mock oracle contract
contract MockOracle is IOracleProvider {
    OracleVersion private _version;

    function setVersion(uint256 version, uint256 timestamp, Fixed18 price) external {
        _version = OracleVersion(version, timestamp, price);
    }

    function sync() external returns (OracleVersion memory) {
        return _version;
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return _version;
    }

    function atVersion(uint256) external view returns (OracleVersion memory) {
        return _version;
    }
}

// PayoffDefinition library stubs
